package de.mcstack.craftcore;
import java.sql.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class InviteStoreTest {
 static void schema(Connection c)throws Exception {try(Statement s=c.createStatement()){s.execute("CREATE TABLE accounts(uuid VARCHAR(36) PRIMARY KEY,balance BIGINT NOT NULL)");s.execute("CREATE TABLE invite_reward_notices(invite_id BIGINT PRIMARY KEY,inviter_uuid VARCHAR(36),cp BIGINT,reported BOOLEAN DEFAULT FALSE)");s.execute("CREATE TABLE motivation(uuid VARCHAR(36) PRIMARY KEY,seconds_played BIGINT NOT NULL)");s.execute(InviteStore.DDL);s.execute("INSERT INTO accounts VALUES('inviter',123)");s.execute("INSERT INTO motivation VALUES('guest',7199)");s.execute("INSERT INTO invites(inviter_uuid,invitee_uuid) VALUES('inviter','guest')");}}
 static long balance(Connection c)throws Exception {try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT balance FROM accounts WHERE uuid='inviter'")){r.next();return r.getLong(1);}}
 static void check(Connection c)throws Exception {c.setAutoCommit(false);assertNull(InviteStore.reward(c,1,7200,50000));assertEquals(123,balance(c));try(Statement s=c.createStatement()){s.execute("UPDATE motivation SET seconds_played=7200 WHERE uuid='guest'");}assertEquals("inviter",InviteStore.reward(c,1,7200,50000));assertEquals(50123,balance(c));assertNull(InviteStore.reward(c,1,7200,50000));try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT rewarded,paid_at FROM invites WHERE id=1")){assertTrue(r.next());assertTrue(r.getBoolean(1));assertNotNull(r.getTimestamp(2));}c.rollback();}
 @Test void thresholdAndRollback()throws Exception {try(Connection c=DriverManager.getConnection("jdbc:h2:mem:invites_test;MODE=MySQL;DB_CLOSE_DELAY=-1")){schema(c);check(c);assertEquals(123,balance(c));}}
 @Test void parallelPayoutOnlyOnce()throws Exception {String url="jdbc:h2:mem:invites_parallel;MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000";try(Connection setup=DriverManager.getConnection(url)){schema(setup);try(Statement s=setup.createStatement()){s.execute("UPDATE motivation SET seconds_played=7200");}}ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{Callable<String> task=()->{try(Connection c=DriverManager.getConnection(url)){c.setAutoCommit(false);start.await();String result=InviteStore.reward(c,1,7200,50000);c.commit();return result;}};Future<String> a=pool.submit(task),b=pool.submit(task);start.countDown();String x=a.get(),y=b.get();assertTrue((x==null) != (y==null));try(Connection c=DriverManager.getConnection(url)){assertEquals(50123,balance(c));}}finally{pool.shutdownNow();}}
}
